// Private primitive: actual original Q8 vocabulary versus current BF16 cache.
#include "flash/FlashDenseCache.hpp"
#include "flash/FlashDenseSmallRows.hpp"
#include "flash/FlashGreedyGPU.hpp"
#include "metal/abi/FlashInt8Head.h"
#include "metal/abi/FlashDenseSmallRows.h"
#include "engine/Json.hpp"
#import <Foundation/Foundation.h>
#include <algorithm>
#include <array>
#include <bit>
#include <cmath>
#include <cstdlib>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <numeric>
#include <span>
#include <sstream>
#include <stdexcept>
#include <vector>
using namespace splash::flash;
using namespace splash::metal;
namespace {
constexpr uint32_t N=248320,K=2560,R=4,Sticky=0x40000000;
constexpr uint16_t Sentinel=0x7fc1;
void require(bool ok,const char *message){if(!ok)throw std::runtime_error(message);}
float number(uint16_t x){return std::bit_cast<float>(uint32_t{x}<<16);}
uint16_t bf16(float v){const uint32_t x=std::bit_cast<uint32_t>(v);return uint16_t((x+0x7fff+((x>>16)&1u))>>16);}
uint64_t randomWord(uint64_t x){x+=0x9e3779b97f4a7c15ull;x=(x^(x>>30))*0xbf58476d1ce4e5b9ull;x=(x^(x>>27))*0x94d049bb133111ebull;return x^(x>>31);}
struct Variant {uint32_t n,bk,sg;std::string name()const{return "flash_joint_q8_exact_bf16_v9_m8_n"+std::to_string(n)+"_k"+std::to_string(bk)+"_s"+std::to_string(sg);}};
const std::array<Variant,5> variants{{{64,64,4},{64,128,4},{128,64,4},{128,128,4},{64,128,2}}};
std::vector<uint32_t> choices(){const char *raw=std::getenv("FLASH_Q8_EXACT_VARIANTS");std::vector<uint32_t> out;if(!raw)return {0,1,2,3,4};std::stringstream in(raw);std::string s;while(std::getline(in,s,',')){size_t used=0;auto v=std::stoul(s,&used);require(used==s.size()&&v<variants.size(),"invalid variants");out.push_back(uint32_t(v));}require(!out.empty(),"empty variants");return out;}
uint32_t integer(const char *name,uint32_t fallback,uint32_t maximum){const char *raw=std::getenv(name);if(!raw)return fallback;size_t used=0;auto v=std::stoul(raw,&used);require(used==std::strlen(raw)&&v>0&&v<=maximum,"invalid positive integer control");return uint32_t(v);}
struct Guard {MetalBuffer allocation,view;Guard(MetalBackend &backend){allocation=backend.allocateBuffer(uint64_t(R*N+64)*2,BufferStorage::Shared,"private exact Q8 guarded output");view=backend.view(allocation,64,uint64_t(R)*N*2);clear();}void clear(){std::fill_n(static_cast<uint16_t *>(allocation.contents()),R*N+64,Sentinel);}void check()const{const auto *p=static_cast<const uint16_t *>(allocation.contents());for(uint32_t i=0;i<32;++i)require(p[i]==Sentinel&&p[R*N+32+i]==Sentinel,"guard overwritten");}std::span<const uint16_t> words()const{return {static_cast<const uint16_t *>(view.contents()),R*N};}};
struct Times {std::vector<double> gpu,wall;void add(CommandTiming t){require(t.gpuSeconds>0&&std::isfinite(t.gpuSeconds),"invalid timing");gpu.push_back(t.gpuSeconds);wall.push_back(t.wallSeconds);}static double median(std::vector<double> x){std::sort(x.begin(),x.end());return x.size()%2?x[x.size()/2]:(x[x.size()/2]+x[x.size()/2-1])*.5;}void write(std::ostream &out)const{out<<"{\"median_gpu_seconds\":"<<median(gpu)<<",\"median_wall_seconds\":"<<median(wall)<<",\"gpu_seconds\":[";for(size_t i=0;i<gpu.size();++i){if(i)out<<',';out<<gpu[i];}out<<"]}";}};
struct Metrics {uint64_t mismatches=0,nonfinite=0;double error=0,norm=0,maximum=0;void add(uint16_t a,uint16_t b){mismatches+=a!=b;float aa=number(a),bb=number(b);if(!std::isfinite(aa)||!std::isfinite(bb)){++nonfinite;return;}double d=double(aa)-bb;error+=d*d;norm+=double(aa)*aa;maximum=std::max(maximum,std::abs(d));}double l2()const{return std::sqrt(error/std::max(norm,1e-30));}void write(std::ostream &out)const{out<<"{\"bf16_mismatches\":"<<mismatches<<",\"nonfinite\":"<<nonfinite<<",\"relative_l2\":"<<l2()<<",\"max_absolute_error\":"<<maximum<<",\"strict_bound\":0.0001,\"strict_pass\":"<<(!nonfinite&&l2()<=1e-4?"true":"false")<<'}';}};
FlashInt8HeadParams params(const FlashAffineProjection &p,uint32_t n){return {R,8,K,N,8,64,8,n,p.weightRowStrideBytes,p.parameterRowStrideBytes};}
void candidate(CommandGraph &graph,const FlashAffineProjection &source,MetalBuffer input,MetalBuffer padded,MetalBuffer output,MetalBuffer diagnostics,Variant v){const auto p=params(source,v.n);FlashDenseSmallRowsParams padding{R,8,K,N,0,N,8,v.n};graph.add("flash_dense_small_rows_pad",{input,padded,diagnostics},padding,{(uint64_t{8}*K+255)/256,1,1},{256,1,1});graph.add(v.name(),{padded,source.weights->buffer,source.scales->buffer,source.biases->buffer,padded,output,diagnostics},p,{N/v.n,1,1},{v.sg*32,1,1});}
std::vector<uint16_t> inputs(uint32_t pattern){std::vector<uint16_t> out(R*K);for(uint32_t row=0;row<R;++row){double norm=0;for(uint32_t k=0;k<K;++k){float f=0;if(pattern==0)f=float(int(randomWord(k+row*K+0x18827)%2047)-1023)/512.f;else if(pattern==1)f=(k&1)?-1.25f:1.25f;else if(pattern==2)f=(k%64<32)?32.f:-32.f;else f=(k%32==row)?1.f:0.f;out[row*K+k]=bf16(f);norm+=double(number(out[row*K+k]))*number(out[row*K+k]);}if(pattern==0){float inverse=float(std::sqrt(K/norm));for(uint32_t k=0;k<K;++k)out[row*K+k]=bf16(number(out[row*K+k])*inverse);}}if(pattern==0){const char *path=std::getenv("FLASH_Q8_EXACT_INPUT_BF16");if(path){std::ifstream in(path,std::ios::binary|std::ios::ate);require(bool(in),"cannot open captured input");const auto bytes=in.tellg();require(bytes==K*2||bytes==R*K*2,"captured input must contain 1 or4 exact rows");in.seekg(0);in.read(reinterpret_cast<char *>(out.data()),bytes);require(bool(in),"cannot read captured input");if(bytes==K*2)for(uint32_t row=1;row<R;++row)std::copy_n(out.begin(),K,out.begin()+row*K);}}return out;}
void cpu(){require(sizeof(CommandTiming)==200,"ABI200 required");uint64_t checks=0;for(auto v:variants){std::vector<uint32_t> coverage(N);for(uint32_t g=0;g<N/v.n;++g)for(uint32_t j=0;j<v.n;++j){++coverage[g*v.n+j];++checks;}for(auto hit:coverage)require(hit==1,"column coverage differs");for(uint32_t origin=0;origin<K;origin+=v.bk)for(uint32_t k=0;k<v.bk;++k){require((origin+k)/64==origin/64+k/64,"scale group address differs");++checks;}require(v.n*v.bk*2<=32768,"threadgroup memory exceeds32KiB");}std::cout<<"{\"pass\":true,\"gpu_commands\":0,\"cpu_checks\":"<<checks<<",\"command_timing_abi_bytes\":200}\n";}
}
int main(int argc,char **argv){@autoreleasepool {try {
  if(argc==2&&std::string_view(argv[1])=="--cpu-self-test"){cpu();return 0;}
  if(argc==2&&std::string_view(argv[1])=="--help"){std::cout<<"usage: ORACLE METALLIB PACKAGE REPORT_JSON | --cpu-self-test\nRoot-only GPU. Actual Q8 source vs cached BF16 full vocabulary B4. Controls FLASH_Q8_EXACT_VARIANTS=0..4, FLASH_Q8_EXACT_PATTERNS=1..4, FLASH_Q8_EXACT_PAIRS=1..12, FLASH_Q8_EXACT_INPUT_BF16=file. Full coefficient GPU audit always runs.\n";return 0;}
  require(argc==4,"usage: ORACLE METALLIB PACKAGE REPORT_JSON");require(!std::filesystem::exists(argv[3]),"choose a fresh report");static_assert(sizeof(CommandTiming)==200);
  const auto selected=choices();const uint32_t patterns=integer("FLASH_Q8_EXACT_PATTERNS",4,4),pairs=integer("FLASH_Q8_EXACT_PAIRS",6,12);
  MetalBackend backend(argv[1]);const auto weights=FlashWeights::load(backend,argv[2]);const auto &source=weights.projection("language_model.lm_head");require(source.inputSize==K&&source.outputSize==N&&source.bits==8&&source.groupSize==64,"wrong original Q8 source");
  const std::array<std::string,1> prefixes{"language_model.lm_head"};FlashDenseCache cache(backend,weights,prefixes);const auto &cached=cache.tensor(prefixes[0]);
  auto input=backend.allocateBuffer(R*K*2,BufferStorage::Shared,"private B4 exact input");auto padded=backend.allocateBuffer(8*K*2,BufferStorage::Shared,"private B4 exact padding");auto d0=backend.allocateBuffer(4,BufferStorage::Shared,"private exact control diagnostics"),d1=backend.allocateBuffer(4,BufferStorage::Shared,"private exact candidate diagnostics");auto audit=backend.allocateBuffer(8,BufferStorage::Shared,"private full coefficient audit counts");std::memset(audit.contents(),0,8);
  CommandGraph coefficientGraph;coefficientGraph.add("flash_joint_q8_exact_bf16_v9_audit",{source.weights->buffer,source.scales->buffer,source.biases->buffer,cached.buffer,audit},params(source,64),{(uint64_t{N}*K+255)/256,1,1},{256,1,1});const auto coefficientTiming=backend.submitCommand(coefficientGraph.dispatches());const auto *auditCounts=static_cast<const uint32_t *>(audit.contents());require(auditCounts[0]==0&&auditCounts[1]==0,"full actual coefficient audit failed before candidate execution");
  Guard original(backend),output(backend);FlashDenseSmallRowsWorkspace workspace(backend,K);auto greedy=allocateGreedyGPUWorkspace(backend,R,N);auto greedy0=backend.allocateBuffer(R*16,BufferStorage::Shared,"private original greedy"),greedy1=backend.allocateBuffer(R*16,BufferStorage::Shared,"private candidate greedy");
  std::vector<std::string> records;bool valid=auditCounts[0]==0&&auditCounts[1]==0;uint64_t commands=1;
  for(uint32_t pattern=0;pattern<patterns;++pattern){const auto host=inputs(pattern);std::memcpy(input.contents(),host.data(),R*K*2);CommandGraph control;addDenseBF16SmallRows(backend,control,input,cached,original.view,d0,R,workspace,FlashDenseSmallRowsTile::M8N128);CommandGraph controlComplete;addDenseBF16SmallRows(backend,controlComplete,input,cached,original.view,d0,R,workspace,FlashDenseSmallRowsTile::M8N128);addGreedyGPU(controlComplete,original.view,greedy,greedy0,R,N);*static_cast<uint32_t *>(d0.contents())=Sticky;(void)backend.submitCommand(controlComplete.dispatches());++commands;const std::vector<uint16_t> reference(original.words().begin(),original.words().end());std::array<FlashGreedyGPURowResult,R> referenceGreedy;std::memcpy(referenceGreedy.data(),greedy0.contents(),R*16);
    for(uint32_t index:selected){const auto v=variants[index];CommandGraph graph;candidate(graph,source,input,padded,output.view,d1,v);CommandGraph complete;candidate(complete,source,input,padded,output.view,d1,v);addGreedyGPU(complete,output.view,greedy,greedy1,R,N);*static_cast<uint32_t *>(d1.contents())=Sticky;output.clear();(void)backend.submitCommand(complete.dispatches());++commands;Times base,cand,baseComplete,candComplete;for(uint32_t pair=0;pair<pairs;++pair){if(pair%2==0){base.add(backend.submitCommand(control.dispatches()));cand.add(backend.submitCommand(graph.dispatches()));baseComplete.add(backend.submitCommand(controlComplete.dispatches()));candComplete.add(backend.submitCommand(complete.dispatches()));}else{cand.add(backend.submitCommand(graph.dispatches()));base.add(backend.submitCommand(control.dispatches()));candComplete.add(backend.submitCommand(complete.dispatches()));baseComplete.add(backend.submitCommand(controlComplete.dispatches()));}commands+=4;}original.check();output.check();bool pass=valid;std::array<Metrics,R> metrics;for(uint32_t row=0;row<R;++row)for(uint32_t n=0;n<N;++n)metrics[row].add(reference[row*N+n],output.words()[row*N+n]);for(auto m:metrics)pass=pass&&!m.nonfinite&&m.l2()<=1e-4;const bool exactGreedy=std::memcmp(referenceGreedy.data(),greedy1.contents(),R*16)==0;const bool exactDiagnostics=*static_cast<const uint32_t *>(d0.contents())==Sticky&&*static_cast<const uint32_t *>(d1.contents())==Sticky;pass=pass&&exactGreedy&&exactDiagnostics;valid=valid&&pass;std::ostringstream record;record<<std::setprecision(17)<<"{\"pattern\":"<<pattern<<",\"input_kind\":"<<splash::json::quote(pattern==0&&std::getenv("FLASH_Q8_EXACT_INPUT_BF16")?"captured-real-normalized-head-input":"synthetic")<<",\"variant\":"<<index<<",\"kernel\":"<<splash::json::quote(v.name())<<",\"pass\":"<<(pass?"true":"false")<<",\"exact_greedy\":"<<(exactGreedy?"true":"false")<<",\"exact_diagnostics\":"<<(exactDiagnostics?"true":"false")<<",\"lanes\":[";for(uint32_t row=0;row<R;++row){if(row)record<<',';metrics[row].write(record);}record<<"],\"original_projection_timing\":";base.write(record);record<<",\"candidate_projection_timing\":";cand.write(record);record<<",\"original_projection_and_greedy_timing\":";baseComplete.write(record);record<<",\"candidate_projection_and_greedy_timing\":";candComplete.write(record);record<<'}';records.push_back(record.str());}
  }
  std::ofstream report(argv[3]);require(bool(report),"cannot write report");report<<std::setprecision(17)<<"{\"schema\":\"flash-private-joint-q8-exact-bf16-v9-primitive\",\"execution_complete\":true,\"gpu_executed\":true,\"valid\":"<<(valid?"true":"false")<<",\"coefficient_count\":"<<uint64_t{N}*K<<",\"coefficient_bf16_mismatches\":"<<auditCounts[0]<<",\"coefficient_nonfinite_or_geometry_errors\":"<<auditCounts[1]<<",\"coefficient_audit_gpu_seconds\":"<<coefficientTiming.gpuSeconds<<",\"strict_each_lane_relative_l2_bound\":0.0001,\"strict_bound_relaxed\":false,\"source_identity_sha256\":"<<splash::json::quote(weights.sourceIdentity())<<",\"manifest_fingerprint_sha256\":"<<splash::json::quote(weights.manifestFingerprint())<<",\"production_modified\":false,\"all_original_bytes_unchanged\":true,\"numerical_contract\":\"exact same helper and BF16 cast as qualified cache; BF16xBF16 MPP F32 multiply_accumulate across K64/128; reduction alternative must independently pass strict per-lane bound\",\"gpu_commands\":"<<commands<<",\"cases\":[";for(size_t i=0;i<records.size();++i){if(i)report<<',';report<<records[i];}report<<"]}\n";require(bool(report),"report write failed");std::cout<<"Private exact Q8 BF16 primitive complete; valid="<<(valid?"true":"false")<<" report="<<argv[3]<<'\n';return valid?0:2;
}catch(const std::exception &error){std::cerr<<"private exact Q8 BF16: "<<error.what()<<'\n';return 1;}}}
